```javascript
let numOctaves = 6;
let frequency = 0.05;
let amplitude = 0.5;

function setup() {
  createCanvas(windowWidth, windowHeight, WEBGL);
  noStroke();
}

function draw() {
  background(255);
  translate(0, 0, -300);
  rotateY(frameCount * 0.001);
  rotateX(frameCount * 0.001);

  for (let z = -200; z <= 200; z += 5) {
    for (let y = -200; y <= 200; y += 5) {
      for (let x = -200; x <= 200; x += 5) {
        let vol =andelmanNoise(x * frequency, y * frequency, z * frequency, numOctaves);
        let r = map(vol, -1, 1, 0, 255);
        stroke(r, 0, 0);
        point(x, y, z);
      }
    }
  }
}

function andelmanNoise(x, y, z, octaves) {
  let total = 0;
  let frequency = 1;
  let amplitude = 1;
  let maxVolume = 0;
  let minVolume = 1;

  for (let i = 0; i < octaves; i++) {
    total += lerp(
      noise(x * frequency, y * frequency, z * frequency),
      total,
      amplitude
    );
    frequency *= 2;
    amplitude *= 0.5;
  }
  return total;
}

function lerp(a, b, x) {
  return a + (b - a) * x;
}
```

