// Search Functionality
const searchInput = document.querySelector('.search-input');
const searchIcon = document.querySelector('.search-icon');
const errorMessage = document.querySelector('.error-message');
const searchContainer = document.querySelector('.search-container');

searchInput.addEventListener('focus', () => {
  searchIcon.style.transform = 'rotate(45deg)';
});

searchInput.addEventListener('blur', () => {
  searchIcon.style.transform = '';
});

searchInput.addEventListener('input', (e) => {
  const inputValue = e.target.value;
  if (inputValue === '') {
    searchContainer.classList.remove('error');
    errorMessage.style.display = 'none';
  } else {
    // Google Search API Integration
    const apiUrl = `https://www.googleapis.com/customsearch/v1?q=${inputValue}&key=YOUR_GOOGLE_API_KEY`;
    fetch(apiUrl)
      .then((response) => response.json())
      .then((data) => {
        if (data.error) {
          searchContainer.classList.add('error');
          errorMessage.textContent = data.error.message;
          errorMessage.style.display = 'block';
        } else {
          // Predictive Search Logic
          const predictiveSearchText = document.createElement('span');
          predictiveSearchText.textContent = inputValue;
          predictiveSearchText.classList.add('predictive-search-text');
          searchInput.after(predictiveSearchText);
          const predictiveSearchSuggestions = document.createElement('ul');
          predictiveSearchSuggestions.classList.add('predictive-search-suggestions');
          predictiveSearchText.after(predictiveSearchSuggestions);
          data.items.forEach((item) => {
