#include <iostream>
#include <cmath>
#include <vector>

const double mu = 1.0; // символ молекулярной массы
const double alpha = 1.0; // параметр альфа
const double gamma = 1.0; // символ.gamma

// Функция M
double M(const double& zeta, const double& alpha, const double& h) {
  return (zeta * alpha * alpha * zeta * zeta * alpha) / (16 * mu) *
         (3 * (1 + h / (alpha * zeta)) * (1 + h / (alpha * zeta)) * (1 + h / (alpha * zeta)) -
          4 * (1 + h / (alpha * zeta)) * (1 + h / (alpha * zeta)) + 1 -
          4 * (1 + h / (alpha * zeta)) * (1 + h / (alpha * zeta)) * log(1 + h / (alpha * zeta)));
}

// Функция p
double p(const double& zeta, const double& alpha, const double& h, const double& dh_dzeta) {
  return -gamma * (pow(dh_dzeta, 2) / (1 + pow(dh_dzeta, 2))^(3/2) -
                      (1 - alpha * dh_dzeta) / ((alpha * zeta + h) * (1 + pow(dh_dzeta, 2))^(1/2)));
}

// Решение дифференциальных уравнений
void solve(double& zeta, double& t, double& h, double& dh_dzeta, double& p) {
  const double dzeta = 0.01; // шаг по zeta
  const double dt = 0.001; // шаг по t
  const double L = 30.0; // длина zeta

  // начальное условие h(0,t)
  h = 50e-6;

  // начальное условие p(0,t)
  p = 0.022 / (20e-6);

  // начальное условие h(ζ,0)
  double initialCondition[100];
  for (int i = 0; i < 100; i++) {
    initialCondition[i] = 50e-6 + 162e-6 * pow(tanh(i * dzeta - L), 2);
  }

  // решаем уравнение
  for (double t = 0; t < 1; t += dt) {
    for (double zeta = 0; zeta < L; zeta += dzeta) {
      // сходим обработывает
      double hTemp = h;
      double dh_dzetaTemp = dh_dzeta;

      // вычисляем поиск по zeta
      for (int k = 0; k < 100; k++) {
        double MValue = M(zeta + k * dzeta, alpha, h);
        double pH_ddh_dzeta = -1 * (MValue / (alpha * zeta + h)) * (dh_dzetaTemp);
        double dp_dzeta = p(zeta + k * dzeta, alpha, h, dh_dzetaTemp);
        double d2p_dzeta2 = -1 * (MValue / (alpha * zeta + h)) * (pH_ddh_dzetaTemp);

        dh_dzetaTemp = dh_dzetaTemp + dh_dzeta * (dp_dzeta + d2p_dzeta2 * dzeta) * dt;
        h = h + hTemp * (1 / (alpha * zeta + h) * dh_dzetaTemp) * dt;
      }

      // обновляем preconditioning
      dh_dzeta = dh_dzetaTemp;
      h = hTemp;

      // проверяем граничные условия
      if (zeta == 0) {
        h = 50e-6;
        dh_dzeta = 0;
      } else if (zeta == L) {
        h = 50e-6 + 162e-6 * pow(tanh(L - zeta), 2);
      }
    }
  }
}

