```cpp
#include <windows.h>
#include <iostream>
#include <cstdlib>
#include <ctime>

// константы для вычислений
const int N = 1000; // количество точек для интегрирования
const double a = 0; // начале интегрирования
const double b = 1; // конца интегрирования
const double h = (b - a) / N; // шаг метода прямых линий

// функция для вычисления интеграла методом прямоугольников
double integrate_rectangle(double (*f)(double), int i) {
    double sum = 0;
    for (int j = 1; j < N; j++) {
        sum += f(a + j * h);
    }
    return sum * h;
}

// функция для вычисления интеграла методом трапеций
double integrate_trap(double (*f)(double), int i) {
    double sum = 0;
    for (int j = 0; j < N; j++) {
        sum += f(a + j * h) + f(a + (j + 1) * h);
    }
    return (h / 2) * sum;
}

// функция для вычисления интеграла методом Симпсона
double integrate_simpson(double (*f)(double), int i) {
    double sum = 0;
    for (int j = 0; j < N / 2; j++) {
        sum += f(a + 2 * j * h);
    }
    return (h / 3) * (sum + f(a) + f(b) + 4 * sum);
}

// функция для вычисления объекта f(x) = x^2
double func(double x) {
    return x * x;
}

