    // создаем семафор для контроля количества потоков
    HANDLE semaphore = CreateSemaphore(NULL, 0, n, NULL);

    // создаем n потоков
    for (int i = 0; i < n; i++) {
        HANDLE thread = CreateThread(NULL, 0, (LPTHREAD_START_ROUTINE)&thread_func, (LPVOID)&i, 0, NULL);
        if (thread == NULL) {
            std::cerr << "Error creating thread" << std::endl;
            return 1;
        }
    }

    // ожидаем завершения всех потоков
    WaitForMultipleObjects(n, (HANDLE*)&thread, WAIT_ANY, INFINITE);

    // закрываем мьютекс и семафор
    CloseHandle(mutex);
    CloseHandle(semaphore);

    return 0;
}

void thread_func(LPVOID lpParameter) {
    int i = (int)lpParameter;

    // начальные случайные задержки
    Sleep(rand() % 100);

    // вычисление интеграла методом прямоугольников
    double integral_rectangle = integrate_rectangle(func, i);

    // вычисление интеграла методом трапеций
    double integral_trap = integrate_trap(func, i);

    // вычисление интеграла методом Симпсона
    double integral_simpson = integrate_simpson(func, i);

    // синхронизация вывода
    WaitForSingleObject(mutex, INFINITE);
    std::cout << "Thread " << i << ": integral_rectangle = " << integral_rectangle << ", integral_trap = " << integral_trap << ", integral_simpson = " << integral_simpson << std::endl;
    ReleaseMutex(mutex);
}
