        raiz = new Node();
        raiz->valor = valor;
        raiz->izquierda = nullptr;
        raiz->derecha = nullptr;
    } else if (valor < raiz->valor) {
        raiz->izquierda = insertar(raiz->izquierda, valor);
    } else if (valor > raiz->valor) {
        raiz->derecha = insertar(raiz->derecha, valor);
    }
    return raiz;
}

// Función para buscar un valor en el árbol binario
bool buscar(Node* raiz, int valor) {
    if (raiz == nullptr) {
        return false;
    }
    if (valor == raiz->valor) {
        return true;
    }
    if (valor < raiz->valor) {
        return buscar(raiz->izquierda, valor);
    }
    return buscar(raiz->derecha, valor);
}

