    raiz = insertar(raiz, 5);
    insertar(raiz, 2);
    insertar(raiz, 8);
    insertar(raiz, 3);
    insertar(raiz, 9);

    // Buscar un valor en el árbol binario
    int valor = 8;
    if (buscar(raiz, valor)) {
        cout << "Valor encontrado: " << valor << endl;
