```pascal
uses
  TPfdFileMain,
  TPfdFileParser,
  TPdfEngine,
  TPdfPage,
  TPdfDocument;

procedure TForm1.Button1Click(Sender: TObject);
var
  PDFDoc: TPDFDocument;
  Page: TPDFPage;
